-- 17A P3 step (ii): flip chat-images to PRIVATE. Refuses unless P1 + P3a are applied, public-assets holds the moved assets, and NO public table still references 'chat-images'. [APPLY]
-- 17A STORAGE PRIVACY: PROPOSAL ONLY. NOT APPLIED ANYWHERE. GENERATED by db/proposed/17a-storage-privacy/build.mjs (node build.mjs --check fails if this file drifts from its inputs).
-- Apply gate: NO prod SQL and NO Storage API operation without Joe's relayed yes + Sentinel's pass + Atlas's review of the migrations + a backup. Sentinel's inventory/backup files were NOT available to this draft (see README). Order: README.md.
-- Run as postgres, ONE transaction, ON_ERROR_STOP (psql -v ON_ERROR_STOP=1) or a single-call SQL executor; right after BEGIN come SET LOCAL lock_timeout = '5s', the repo-wide pack advisory lock, and SET LOCAL lock_timeout = '5s' again.
-- Run it a second time and it refuses at the guard (state is no longer the captured one) with nothing changed.
-- No object, no row and no data is deleted by this pack.
BEGIN;
-- repo-wide pack key (same as R1 #136 / 12A / 13A): serialises every pack run; transaction-scoped; a second run waits for a running pack to commit or roll back, for at most 5 s:
-- lock_timeout is set BEFORE the lock (so the lock wait itself is bounded) and again right after it (every later lock wait). Expiry = SQLSTATE 55P03, nothing changed.
SET LOCAL lock_timeout = '5s';
SELECT pg_advisory_xact_lock(2979301232487107403);
SET LOCAL lock_timeout = '5s';
SET LOCAL statement_timeout = '120s';

-- 1. DRIFT GUARD: live state must be EXACTLY the captured prod state (policies by name/shape/predicate, bucket settings, ACL classes, prerequisite functions). Anything else aborts with nothing applied.
DO $guard$
DECLARE
  f text[] := ARRAY[]::text[];
  v text;
BEGIN
  IF current_user <> 'postgres' THEN f := f || ('run as postgres; current_user=' || current_user); END IF;
  v := coalesce((SELECT coalesce(string_agg(p.policyname::text, ',' ORDER BY p.policyname::text COLLATE "C"),'(none)') FROM pg_policies p WHERE p.schemaname = 'storage' AND p.tablename = 'objects' AND p.cmd IN ('SELECT','ALL') AND (coalesce(p.qual,'') || ' ' || coalesce(p.with_check,'')) ~ 'chat-images'), 'ABSENT');
  IF v IS DISTINCT FROM 'chat_images_owner_admin_read' THEN f := f || ('req.P1_applied_chat_images: expected chat_images_owner_admin_read but live is ' || v); END IF;
  v := coalesce((SELECT b.public::text FROM storage.buckets b WHERE b.id = 'public-assets'), 'ABSENT');
  IF v IS DISTINCT FROM 'true' THEN f := f || ('req.public_assets_bucket_public: expected true but live is ' || v); END IF;
  v := coalesce(((SELECT count(*) FROM storage.objects o WHERE o.bucket_id = 'public-assets') >= 6)::text, 'ABSENT');
  IF v IS DISTINCT FROM 'true' THEN f := f || ('req.public_assets_object_count_ge_min: expected true but live is ' || v); END IF;
  v := coalesce((WITH cols AS (
  SELECT c.table_name::text AS t, c.column_name::text AS col FROM information_schema.columns c JOIN information_schema.tables tb ON tb.table_schema = c.table_schema AND tb.table_name = c.table_name
  WHERE c.table_schema = 'public' AND tb.table_type = 'BASE TABLE' AND c.data_type IN ('text','character varying','json','jsonb') AND c.table_name NOT LIKE '\_bak\_%'
), hits AS (
  SELECT t, col, (xpath('/row/n/text()', query_to_xml(format('select count(*) as n from public.%I where strpos(%I::text, %L) > 0', t, col, 'chat-images'), false, true, '')))[1]::text::int AS n FROM cols
) SELECT coalesce(string_agg(t || '.' || col || '=' || n, ',' ORDER BY t, col), 'none') FROM hits WHERE n > 0), 'ABSENT');
  IF v IS DISTINCT FROM 'none' THEN f := f || ('req.no_public_table_references_chat_images: expected none but live is ' || v); END IF;
  v := coalesce((SELECT b.public::text FROM storage.buckets b WHERE b.id = 'chat-images'), 'ABSENT');
  IF v IS DISTINCT FROM 'true' THEN f := f || ('bucket.chat-images.public: expected true but live is ' || v); END IF;
  IF array_length(f, 1) IS NOT NULL THEN
    RAISE EXCEPTION '17A APPLY-P3c: DRIFT, ABORT, nothing applied. % mismatch(es): %', array_length(f, 1), array_to_string(f, ' ; ');
  END IF;
END
$guard$;

-- 2. INVARIANT SNAPSHOT: everything this pack must NOT change (ACL fingerprints sorted, RLS flags, every other policy, every untouched bucket row, the object name set).
CREATE TEMP TABLE _kil17a_inv ON COMMIT DROP AS
SELECT 'inv.objects_acl_sorted'::text AS name, coalesce((SELECT coalesce(CASE WHEN c.relacl IS NULL THEN NULL ELSE (SELECT '{'||coalesce(string_agg(acl_e::text,',' ORDER BY acl_e::text COLLATE "C"),'')||'}' FROM unnest(c.relacl) acl_e) END,'(default)') FROM pg_class c WHERE c.oid = 'storage.objects'::regclass), '(null)')::text AS val
UNION ALL SELECT 'inv.buckets_acl_sorted'::text AS name, coalesce((SELECT coalesce(CASE WHEN c.relacl IS NULL THEN NULL ELSE (SELECT '{'||coalesce(string_agg(acl_e::text,',' ORDER BY acl_e::text COLLATE "C"),'')||'}' FROM unnest(c.relacl) acl_e) END,'(default)') FROM pg_class c WHERE c.oid = 'storage.buckets'::regclass), '(null)')::text AS val
UNION ALL SELECT 'inv.objects_rls'::text AS name, coalesce((SELECT c.relrowsecurity::text || '/' || c.relforcerowsecurity::text FROM pg_class c WHERE c.oid = 'storage.objects'::regclass), '(null)')::text AS val
UNION ALL SELECT 'inv.objects_rows_md5'::text AS name, coalesce((SELECT count(*)::text || ':' || coalesce(md5(string_agg(o.bucket_id || '/' || o.name || '/' || coalesce(o.owner_id,''), '|' ORDER BY o.bucket_id, o.name)),'-') FROM storage.objects o), '(null)')::text AS val
UNION ALL SELECT 'inv.other_policies_md5'::text AS name, coalesce((SELECT count(*)::text || ':' || coalesce(md5(string_agg(p.policyname || '|' || p.cmd || '|' || array_to_string(p.roles,',') || '|' || p.permissive || '|' || coalesce(p.qual,'') || '|' || coalesce(p.with_check,''), E'\n' ORDER BY p.policyname COLLATE "C")),'-') FROM pg_policies p WHERE p.schemaname = 'storage' AND p.tablename = 'objects' AND p.policyname NOT IN ('')), '(null)')::text AS val
UNION ALL SELECT 'inv.other_buckets_md5'::text AS name, coalesce((SELECT count(*)::text || ':' || coalesce(md5(string_agg(b::text, '|' ORDER BY b.id)),'-') FROM storage.buckets b WHERE b.id NOT IN ('chat-images')), '(null)')::text AS val;

-- 3. THE FIX
-- flip chat-images to PRIVATE. Public URLs of this bucket stop working immediately: the guard above refuses unless NO public table still references it and public-assets already holds the moved assets.
UPDATE storage.buckets SET public = false WHERE id = 'chat-images';

-- 4. POST-CHECKS (assert; a failure rolls the whole transaction back)
DO $post$
DECLARE bad text;
BEGIN
  SELECT string_agg(name || ' (expected ' || expected || ', got ' || actual || ')', ' ; ') INTO bad FROM (
WITH a(name, actual) AS (
  SELECT 'req.P1_applied_chat_images' AS name, coalesce((SELECT coalesce(string_agg(p.policyname::text, ',' ORDER BY p.policyname::text COLLATE "C"),'(none)') FROM pg_policies p WHERE p.schemaname = 'storage' AND p.tablename = 'objects' AND p.cmd IN ('SELECT','ALL') AND (coalesce(p.qual,'') || ' ' || coalesce(p.with_check,'')) ~ 'chat-images'), 'ABSENT') AS actual
  UNION ALL SELECT 'req.public_assets_bucket_public' AS name, coalesce((SELECT b.public::text FROM storage.buckets b WHERE b.id = 'public-assets'), 'ABSENT') AS actual
  UNION ALL SELECT 'req.public_assets_object_count_ge_min' AS name, coalesce(((SELECT count(*) FROM storage.objects o WHERE o.bucket_id = 'public-assets') >= 6)::text, 'ABSENT') AS actual
  UNION ALL SELECT 'req.no_public_table_references_chat_images' AS name, coalesce((WITH cols AS (
  SELECT c.table_name::text AS t, c.column_name::text AS col FROM information_schema.columns c JOIN information_schema.tables tb ON tb.table_schema = c.table_schema AND tb.table_name = c.table_name
  WHERE c.table_schema = 'public' AND tb.table_type = 'BASE TABLE' AND c.data_type IN ('text','character varying','json','jsonb') AND c.table_name NOT LIKE '\_bak\_%'
), hits AS (
  SELECT t, col, (xpath('/row/n/text()', query_to_xml(format('select count(*) as n from public.%I where strpos(%I::text, %L) > 0', t, col, 'chat-images'), false, true, '')))[1]::text::int AS n FROM cols
) SELECT coalesce(string_agg(t || '.' || col || '=' || n, ',' ORDER BY t, col), 'none') FROM hits WHERE n > 0), 'ABSENT') AS actual
  UNION ALL SELECT 'bucket.chat-images.public' AS name, coalesce((SELECT b.public::text FROM storage.buckets b WHERE b.id = 'chat-images'), 'ABSENT') AS actual
), e(name, expected, accepted) AS (VALUES
  ('req.P1_applied_chat_images', 'chat_images_owner_admin_read', ARRAY['chat_images_owner_admin_read']::text[]),
  ('req.public_assets_bucket_public', 'true', ARRAY['true']::text[]),
  ('req.public_assets_object_count_ge_min', 'true', ARRAY['true']::text[]),
  ('req.no_public_table_references_chat_images', 'none', ARRAY['none']::text[]),
  ('bucket.chat-images.public', 'false', ARRAY['false']::text[])
), r AS (SELECT e.name, coalesce(e.expected, 'RECORD ONLY') AS expected, a.actual, (e.accepted IS NULL OR a.actual = ANY (e.accepted)) AS ok FROM e LEFT JOIN a USING (name))
SELECT name, expected, actual, ok FROM r
  ) z WHERE NOT ok;
  IF bad IS NOT NULL THEN RAISE EXCEPTION '17A APPLY-P3c: POST-CHECK FAILED (transaction rolls back): %', bad; END IF;
END
$post$;
DO $invcheck$
DECLARE bad text;
BEGIN
  SELECT string_agg(a.name, ', ') INTO bad FROM _kil17a_inv a JOIN (
    SELECT 'inv.objects_acl_sorted'::text AS name, coalesce((SELECT coalesce(CASE WHEN c.relacl IS NULL THEN NULL ELSE (SELECT '{'||coalesce(string_agg(acl_e::text,',' ORDER BY acl_e::text COLLATE "C"),'')||'}' FROM unnest(c.relacl) acl_e) END,'(default)') FROM pg_class c WHERE c.oid = 'storage.objects'::regclass), '(null)')::text AS val
    UNION ALL SELECT 'inv.buckets_acl_sorted'::text AS name, coalesce((SELECT coalesce(CASE WHEN c.relacl IS NULL THEN NULL ELSE (SELECT '{'||coalesce(string_agg(acl_e::text,',' ORDER BY acl_e::text COLLATE "C"),'')||'}' FROM unnest(c.relacl) acl_e) END,'(default)') FROM pg_class c WHERE c.oid = 'storage.buckets'::regclass), '(null)')::text AS val
    UNION ALL SELECT 'inv.objects_rls'::text AS name, coalesce((SELECT c.relrowsecurity::text || '/' || c.relforcerowsecurity::text FROM pg_class c WHERE c.oid = 'storage.objects'::regclass), '(null)')::text AS val
    UNION ALL SELECT 'inv.objects_rows_md5'::text AS name, coalesce((SELECT count(*)::text || ':' || coalesce(md5(string_agg(o.bucket_id || '/' || o.name || '/' || coalesce(o.owner_id,''), '|' ORDER BY o.bucket_id, o.name)),'-') FROM storage.objects o), '(null)')::text AS val
    UNION ALL SELECT 'inv.other_policies_md5'::text AS name, coalesce((SELECT count(*)::text || ':' || coalesce(md5(string_agg(p.policyname || '|' || p.cmd || '|' || array_to_string(p.roles,',') || '|' || p.permissive || '|' || coalesce(p.qual,'') || '|' || coalesce(p.with_check,''), E'\n' ORDER BY p.policyname COLLATE "C")),'-') FROM pg_policies p WHERE p.schemaname = 'storage' AND p.tablename = 'objects' AND p.policyname NOT IN ('')), '(null)')::text AS val
    UNION ALL SELECT 'inv.other_buckets_md5'::text AS name, coalesce((SELECT count(*)::text || ':' || coalesce(md5(string_agg(b::text, '|' ORDER BY b.id)),'-') FROM storage.buckets b WHERE b.id NOT IN ('chat-images')), '(null)')::text AS val
  ) b USING (name) WHERE a.val IS DISTINCT FROM b.val;
  IF bad IS NOT NULL THEN RAISE EXCEPTION '17A APPLY-P3c: INVARIANT CHANGED (the pack must change nothing else; transaction rolls back): %', bad; END IF;
END
$invcheck$;

-- 5. RETAINED OUTPUT: keep this result set with the change record (ok must be true on every row).
WITH a(name, actual) AS (
  SELECT 'req.P1_applied_chat_images' AS name, coalesce((SELECT coalesce(string_agg(p.policyname::text, ',' ORDER BY p.policyname::text COLLATE "C"),'(none)') FROM pg_policies p WHERE p.schemaname = 'storage' AND p.tablename = 'objects' AND p.cmd IN ('SELECT','ALL') AND (coalesce(p.qual,'') || ' ' || coalesce(p.with_check,'')) ~ 'chat-images'), 'ABSENT') AS actual
  UNION ALL SELECT 'req.public_assets_bucket_public' AS name, coalesce((SELECT b.public::text FROM storage.buckets b WHERE b.id = 'public-assets'), 'ABSENT') AS actual
  UNION ALL SELECT 'req.public_assets_object_count_ge_min' AS name, coalesce(((SELECT count(*) FROM storage.objects o WHERE o.bucket_id = 'public-assets') >= 6)::text, 'ABSENT') AS actual
  UNION ALL SELECT 'req.no_public_table_references_chat_images' AS name, coalesce((WITH cols AS (
  SELECT c.table_name::text AS t, c.column_name::text AS col FROM information_schema.columns c JOIN information_schema.tables tb ON tb.table_schema = c.table_schema AND tb.table_name = c.table_name
  WHERE c.table_schema = 'public' AND tb.table_type = 'BASE TABLE' AND c.data_type IN ('text','character varying','json','jsonb') AND c.table_name NOT LIKE '\_bak\_%'
), hits AS (
  SELECT t, col, (xpath('/row/n/text()', query_to_xml(format('select count(*) as n from public.%I where strpos(%I::text, %L) > 0', t, col, 'chat-images'), false, true, '')))[1]::text::int AS n FROM cols
) SELECT coalesce(string_agg(t || '.' || col || '=' || n, ',' ORDER BY t, col), 'none') FROM hits WHERE n > 0), 'ABSENT') AS actual
  UNION ALL SELECT 'bucket.chat-images.public' AS name, coalesce((SELECT b.public::text FROM storage.buckets b WHERE b.id = 'chat-images'), 'ABSENT') AS actual
), e(name, expected, accepted) AS (VALUES
  ('req.P1_applied_chat_images', 'chat_images_owner_admin_read', ARRAY['chat_images_owner_admin_read']::text[]),
  ('req.public_assets_bucket_public', 'true', ARRAY['true']::text[]),
  ('req.public_assets_object_count_ge_min', 'true', ARRAY['true']::text[]),
  ('req.no_public_table_references_chat_images', 'none', ARRAY['none']::text[]),
  ('bucket.chat-images.public', 'false', ARRAY['false']::text[])
), r AS (SELECT e.name, coalesce(e.expected, 'RECORD ONLY') AS expected, a.actual, (e.accepted IS NULL OR a.actual = ANY (e.accepted)) AS ok FROM e LEFT JOIN a USING (name))
SELECT '000_ALL_OK' AS name, 'POST' AS expected, 'POST' AS actual, bool_and(ok) AS ok FROM r
UNION ALL SELECT name, expected, actual, ok FROM r
ORDER BY 1;
COMMIT;
